// TH16 v1.00a Stage 6 BossCard2 (spell 74) — source st06bs.ecl.txt:916-975,
// dependency BossCard2_at:977-1085. Approved TH16 alias of the TH18 type-25 slot.
const TH16_FIREBALL_RED: int = 752;   // source etSprite(0, 25, 0)

const TIME_LIMIT: int = 3124;         // meta.time_limit: 120 opening buffer + 3000 source window + 4 slack
const OPENING_BUFFER: int = 120;
const SOURCE_FRAMES: int = 3000;      // source setInterrupt(0,0,3000) / spell(74,3000) window

// BossCard2_at random angle ranges: 0.17453292 rad = 10 deg, 0.7853982 rad = 45 deg, in BAM.
const AMOUNT_10: int = 1820;
const AMOUNT_45: int = 8192;
const INV_65536: fx = 0.0000152587890625fx;   // 1 raw unit of Q16.16

xformdef VEL_RAMP {
    // source etEx(0,0,0x200000,120,-999999,1.0f,-999999): VELTIME keeps the angle and
    // ramps the scalar speed to 1.0 over 120 frames (birth ANIM stage omitted per policy).
    step_speed(1fx, 120 + 65536 * EASE_LINEAR);
}

// One source etOn: etSpeed(0, 0.1+RANDF*0.5, 0), then etAngle(0, base+RANDF2*amount, 0.5235988), etOn.
// ways = source etCount: 1 on Easy/Normal, 2 on Hard/Lunatic (fixed fan at +-15 deg around base).
sub shoot_wave(x: fx, y: fx, base: int, amount: int, ways: int) {
    var u: fx = (rand(65536) - 32768) as fx * INV_65536 + 0.5fx;   // RANDF in [0,1)
    var sp: fx = 0.1fx + u * 0.5fx;
    var r: int = (rand(65536) - 32768) * amount / 32768;         // RANDF2 in [-1,1) * amount
    var c: int = base + r;
    var a0: angle = (c + 2731) as angle;   // source fan order: F(2,0)=+delta/2 first (delta=30 deg)
    // ANIM entry keeps position -= 4*velocity (birth deceleration/no-hit window is omitted).
    _ = fire(TH16_FIREBALL_RED, 0, x - 4fx * sp * cos(a0), y - 4fx * sp * sin(a0),
             sp, a0, VEL_RAMP, none);
    if ways > 1 {
        var a1: angle = (c - 2731) as angle;   // F(2,1)=-delta/2
        _ = fire(TH16_FIREBALL_RED, 0, x - 4fx * sp * cos(a1), y - 4fx * sp * sin(a1),
                 sp, a1, VEL_RAMP, none);
    }
}

async sub boss_card() {
    set_invuln(65535);
    set_hitbox(25fx);    // Boss entry setHitbox(50,50): ordinary circular branch -> r=25
    set_hurtbox(28fx);   // Boss entry setHurtbox(56,56) -> r=28

    // Entry: source moveVel(0,0)/moveVelTime(0,0,0,0)/movePosTime(0,0,0,0) only stop the
    // previous card's motion; the fresh enemy has none. movePosTime(60,4,0,128) keeps its
    // quad-out easing; the independent card starts at its target point (0,128).
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);

    wait(90);   // source +90 time gate before the first BossCard2_at burst
    var t: int = 90;
    var ways: int = 1;
    var delay: int = 10;
    var n1: int = 9;
    var c1: fx = 20fx;
    var n2: int = 14;
    var c2: fx = 32fx;
    var n3: int = 9;
    var c3: fx = 20fx;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL {
        delay = 5; n1 = 19; c1 = 10fx; n2 = 28; c2 = 16fx; n3 = 19; c3 = 10fx;
    } else if rank == RANK_HARD {
        ways = 2; delay = 8; n1 = 12; c1 = 15fx; n2 = 18; c2 = 24fx; n3 = 12; c3 = 15fx;
    } else if rank >= RANK_LUNATIC {
        ways = 2; delay = 6; n1 = 16; c1 = 12fx; n2 = 22; c2 = 20fx; n3 = 16; c3 = 12fx;
    }

    // BossCard2_at: its inner $D=10000 round loop cannot finish inside the 3000-frame window,
    // so the card-level moveRand/wait(40)/$C loop (source 962-973) is unreachable in this card.
    while t < SOURCE_FRAMES {
        // Phase 1 (source 468/644/1432): A starts at 0, steps by C; waves at (A,0) and (-A,0), 90 deg.
        var a: fx = 0fx;
        var i: int = 0;
        while i < n1 && t < SOURCE_FRAMES {
            a = a + c1;
            shoot_wave(a, 0fx, 16384, AMOUNT_10, ways);
            shoot_wave(0fx - a, 0fx, 16384, AMOUNT_10, ways);
            wait(delay);
            t = t + delay;
            i = i + 1;
        }
        // Phase 2 (source 1028/1612/2364): B starts at 0, steps by C; waves at (192,B) 180 deg
        // and (-192,B) 0 deg.
        var b: fx = 0fx;
        i = 0;
        while i < n2 && t < SOURCE_FRAMES {
            b = b + c2;
            shoot_wave(192fx, b, 32768, AMOUNT_10, ways);
            shoot_wave(-192fx, b, 0, AMOUNT_10, ways);
            wait(delay);
            t = t + delay;
            i = i + 1;
        }
        // Phase 3 (source 1054/2584/3372): A starts at 192 and decreases by C; waves at (A,448)
        // and (-A,448), -90 deg with +-45 deg random.
        a = 192fx;
        i = 0;
        while i < n3 && t < SOURCE_FRAMES {
            a = a - c3;
            shoot_wave(a, 448fx, -16384, AMOUNT_45, ways);
            shoot_wave(0fx - a, 448fx, -16384, AMOUNT_45, ways);
            wait(delay);
            t = t + delay;
            i = i + 1;
        }
        // Source wait(60) between rounds; the source interrupt cuts the window at 3000.
        if t + 60 <= SOURCE_FRAMES {
            wait(60);
            t = t + 60;
        } else {
            wait(SOURCE_FRAMES - t);
            t = SOURCE_FRAMES;
        }
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2400, 0, 0, 0, boss_card);   // Boss lifeSet(2400) for spell 74-77
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
